/**
 * Tier-2 numeric helpers for the calc DSL.
 *
 * Each builder is a thin typed wrapper over a wire `FUNC(...)` form.
 * Output brands mirror the Java test's behavior:
 *   - `round` returns NUMBER without places and DECIMAL with places.
 *   - `power`, `sqrt` return DECIMAL (fractional results possible).
 *   - `toNumber` coerces text → NUMBER.
 *   - `uuid` is nullary and returns a `uuid`-branded expression.
 */
import type { ComposedExpr, Expr, ExprLike, NumericLike } from "./types.js";
export declare function round<const Value extends NumericLike>(value: Value): ComposedExpr<"number", [Value]>;
export declare function round<const Value extends NumericLike>(value: Value, digits: 0): ComposedExpr<"number", [Value]>;
export declare function round<const Value extends NumericLike>(value: Value, digits: number): ComposedExpr<"decimal", [Value]>;
export declare function power<const Base extends NumericLike, const Exponent extends NumericLike>(base: Base, exponent: Exponent): ComposedExpr<"decimal", [Base, Exponent]>;
export declare function sqrt<const Value extends NumericLike>(value: Value): ComposedExpr<"decimal", [Value]>;
export declare function toNumber<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"number", [Value]>;
export declare function uuid(): Expr<"uuid">;
